BACKEND_EXPORT_BLOCK = '// Team Performance Export Routes\nasync function buildTeamPerformanceExportDataset(req, payload = {}) {\n  const { start, end, employeeId, department, projectId, status, search } = payload || {};\n  if (!start || !end) throw new AppError("start and end are required", 400);\n\n  const startDate = new Date(start);\n  const endDate = new Date(end);\n  if (Number.isNaN(startDate.getTime()) || Number.isNaN(endDate.getTime())) throw new AppError("Invalid export date range", 400);\n  if (startDate > endDate) throw new AppError("start must be before or equal end", 400);\n\n  const isAdmin = isSystemAdmin(req.user);\n  const isManager = req.user.role === "MANAGER" || req.user.role === "PROJECT_MANAGER";\n  let accessibleProjectIds = [];\n  let accessibleUserIds = [];\n\n  if (isAdmin) {\n    const [projects, users] = await Promise.all([\n      prisma.project.findMany({ where: { archivedAt: null }, select: { id: true } }),\n      prisma.user.findMany({ where: { role: { notIn: ["CLIENT", "FORMER_EMPLOYEE"] } }, select: { id: true } }),\n    ]);\n    accessibleProjectIds = projects.map((item) => item.id);\n    accessibleUserIds = users.map((item) => item.id);\n  } else if (isManager) {\n    const projects = await prisma.project.findMany({\n      where: { archivedAt: null, members: { some: { userId: req.user.id } } },\n      select: { id: true, members: { select: { userId: true } } },\n    });\n    accessibleProjectIds = projects.map((item) => item.id);\n    accessibleUserIds = [...new Set(projects.flatMap((item) => item.members.map((member) => member.userId)))];\n  } else {\n    // Keep the export scope identical to the existing Team Performance endpoint.\n    accessibleUserIds = [req.user.id];\n  }\n\n  let scopedProjectIds = accessibleProjectIds;\n  if (projectId) {\n    if (!accessibleProjectIds.includes(projectId)) throw new AppError("Unauthorized project filter", 403);\n    scopedProjectIds = [projectId];\n  }\n\n  if (employeeId && !accessibleUserIds.includes(employeeId)) throw new AppError("Unauthorized employee filter", 403);\n\n  let users = await prisma.user.findMany({\n    where: {\n      id: { in: accessibleUserIds },\n      role: { notIn: ["CLIENT", "FORMER_EMPLOYEE"] },\n    },\n    select: { id: true, name: true, email: true, role: true, department: true, jobTitle: true, avatarUrl: true },\n    orderBy: [{ role: "asc" }, { name: "asc" }],\n  });\n\n  if (employeeId) users = users.filter((item) => item.id === employeeId);\n  if (department) {\n    const normalizedDepartment = String(department).trim().toLowerCase();\n    users = users.filter((item) => String(item.department || "").trim().toLowerCase() === normalizedDepartment);\n  }\n\n  const searchValue = String(search || "").trim().toLowerCase();\n  if (searchValue) {\n    users = users.filter((item) =>\n      `${item.name || ""} ${item.email || ""} ${item.jobTitle || ""} ${item.department || ""}`\n        .toLowerCase()\n        .includes(searchValue)\n    );\n  }\n\n  const scopedUserIds = users.map((item) => item.id);\n  const timeRange = { gte: startDate, lte: endDate };\n  const durationMs = endDate.getTime() - startDate.getTime();\n  const prevEnd = new Date(startDate.getTime() - 1);\n  const prevStart = new Date(prevEnd.getTime() - durationMs);\n  const prevTimeRange = { gte: prevStart, lte: prevEnd };\n\n  const currentTaskWhere = {\n    archivedAt: null,\n    assigneeId: { in: scopedUserIds },\n    projectId: { in: scopedProjectIds },\n    OR: [\n      { createdAt: timeRange },\n      { updatedAt: timeRange },\n      { startDate: timeRange },\n      { dueDate: timeRange },\n      { completedAt: timeRange },\n    ],\n  };\n\n  const previousTaskWhere = {\n    archivedAt: null,\n    assigneeId: { in: scopedUserIds },\n    projectId: { in: scopedProjectIds },\n    OR: [\n      { createdAt: prevTimeRange },\n      { updatedAt: prevTimeRange },\n      { startDate: prevTimeRange },\n      { dueDate: prevTimeRange },\n      { completedAt: prevTimeRange },\n    ],\n  };\n\n  const [currentTasks, currentActivities, previousTasks, previousActivities] = await Promise.all([\n    prisma.task.findMany({\n      where: currentTaskWhere,\n      select: {\n        id: true,\n        title: true,\n        status: true,\n        priority: true,\n        actualHours: true,\n        estimatedHours: true,\n        dueDate: true,\n        completedAt: true,\n        createdAt: true,\n        updatedAt: true,\n        startDate: true,\n        projectId: true,\n        assigneeId: true,\n        project: { select: { name: true } },\n      },\n    }),\n    prisma.taskActivity.findMany({\n      where: {\n        createdAt: timeRange,\n        task: {\n          archivedAt: null,\n          projectId: { in: scopedProjectIds },\n          assigneeId: { in: scopedUserIds },\n        },\n      },\n      select: {\n        id: true,\n        taskId: true,\n        type: true,\n        metadata: true,\n        createdAt: true,\n        userId: true,\n        task: { select: { assigneeId: true, projectId: true } },\n      },\n    }),\n    prisma.task.findMany({\n      where: previousTaskWhere,\n      select: {\n        id: true,\n        status: true,\n        actualHours: true,\n        estimatedHours: true,\n        dueDate: true,\n        completedAt: true,\n        createdAt: true,\n        updatedAt: true,\n        startDate: true,\n        projectId: true,\n        assigneeId: true,\n      },\n    }),\n    prisma.taskActivity.findMany({\n      where: {\n        createdAt: prevTimeRange,\n        task: {\n          archivedAt: null,\n          projectId: { in: scopedProjectIds },\n          assigneeId: { in: scopedUserIds },\n        },\n      },\n      select: {\n        id: true,\n        taskId: true,\n        type: true,\n        metadata: true,\n        createdAt: true,\n        userId: true,\n        task: { select: { assigneeId: true, projectId: true } },\n      },\n    }),\n  ]);\n\n  const tasksByUser = new Map();\n  const activitiesByUser = new Map();\n  const previousTasksByUser = new Map();\n  const previousActivitiesByUser = new Map();\n\n  for (const task of currentTasks) {\n    if (!tasksByUser.has(task.assigneeId)) tasksByUser.set(task.assigneeId, []);\n    tasksByUser.get(task.assigneeId).push(task);\n  }\n  for (const activity of currentActivities) {\n    const assigneeId = activity.task?.assigneeId;\n    if (!assigneeId) continue;\n    if (!activitiesByUser.has(assigneeId)) activitiesByUser.set(assigneeId, []);\n    activitiesByUser.get(assigneeId).push(activity);\n  }\n  for (const task of previousTasks) {\n    if (!previousTasksByUser.has(task.assigneeId)) previousTasksByUser.set(task.assigneeId, []);\n    previousTasksByUser.get(task.assigneeId).push(task);\n  }\n  for (const activity of previousActivities) {\n    const assigneeId = activity.task?.assigneeId;\n    if (!assigneeId) continue;\n    if (!previousActivitiesByUser.has(assigneeId)) previousActivitiesByUser.set(assigneeId, []);\n    previousActivitiesByUser.get(assigneeId).push(activity);\n  }\n\n  let rows = users.map((item) => {\n    const current = calculatePeriodMetrics(tasksByUser.get(item.id) || [], activitiesByUser.get(item.id) || [], endDate);\n    const previous = calculatePeriodMetrics(previousTasksByUser.get(item.id) || [], previousActivitiesByUser.get(item.id) || [], prevEnd);\n    return {\n      id: item.id,\n      name: item.name,\n      email: item.email,\n      role: item.role,\n      department: item.department,\n      jobTitle: item.jobTitle,\n      avatarUrl: item.avatarUrl,\n      ...current,\n      previous,\n      trend: calculateTrend(current, previous),\n      rank: null,\n    };\n  });\n\n  if (status) rows = rows.filter((item) => (item.status || "No Activity") === status);\n\n  rows.sort((a, b) => {\n    if (a.performanceScore == null && b.performanceScore == null) return String(a.name || "").localeCompare(String(b.name || ""));\n    if (a.performanceScore == null) return 1;\n    if (b.performanceScore == null) return -1;\n    if (b.performanceScore !== a.performanceScore) return b.performanceScore - a.performanceScore;\n    return String(a.name || "").localeCompare(String(b.name || ""));\n  });\n\n  let rank = 1;\n  for (const row of rows) {\n    row.rank = row.performanceScore == null ? null : rank++;\n  }\n\n  const visibleUserIds = new Set(rows.map((item) => item.id));\n  const tasks = currentTasks.filter((task) => visibleUserIds.has(task.assigneeId));\n  const scoredRows = rows.filter((item) => item.performanceScore != null);\n  const completedTasks = rows.reduce((sum, item) => sum + Number(item.completedTasks || 0), 0);\n  const totalTasks = rows.reduce((sum, item) => sum + Number(item.totalTasks || 0), 0);\n  const overdueTasks = rows.reduce((sum, item) => sum + Number(item.overdueTasks || 0), 0);\n  const actualHours = Math.round(rows.reduce((sum, item) => sum + Number(item.actualHours || 0), 0) * 10) / 10;\n  const avgScore = scoredRows.length\n    ? Math.round((scoredRows.reduce((sum, item) => sum + Number(item.performanceScore || 0), 0) / scoredRows.length) * 10) / 10\n    : null;\n\n  return {\n    rows,\n    tasks,\n    summary: {\n      avgScore,\n      topPerformer: scoredRows[0] || null,\n      completedTasks,\n      totalTasks,\n      completionRate: totalTasks ? Math.round((completedTasks / totalTasks) * 100) : 0,\n      overdueTasks,\n      actualHours,\n    },\n    filters: {\n      periodStart: startDate.toISOString(),\n      periodEnd: endDate.toISOString(),\n      employeeFilter: employeeId || null,\n      departmentFilter: department || null,\n      projectFilter: projectId || null,\n      statusFilter: status || null,\n      searchFilter: searchValue || null,\n    },\n  };\n}\n\nfunction teamPerformanceExportFilename(extension, startDate, endDate) {\n  const start = new Date(startDate).toISOString().slice(0, 10);\n  const end = new Date(endDate).toISOString().slice(0, 10);\n  return start === end\n    ? `TOS_Team_Performance_${start}.${extension}`\n    : `TOS_Team_Performance_${start}_to_${end}.${extension}`;\n}\n\nfunction breakdownCell(component) {\n  if (!component || component.skipped) return "Skipped";\n  return `${component.achieved ?? 0}/${component.max ?? 0}`;\n}\n\nrouter.post("/reports/team-performance/export/excel", asyncHandler(async (req, res) => {\n  const dataset = await buildTeamPerformanceExportDataset(req, req.body);\n  const workbook = new ExcelJS.Workbook();\n  workbook.creator = "TOS";\n  workbook.created = new Date();\n\n  const teamSheet = workbook.addWorksheet("Team Performance");\n  teamSheet.addRow(["Rank", "Employee", "Department", "Score", "Confidence", "Completed", "Total Tasks", "Completion %", "Hours", "Overdue", "Trend", "Status"]);\n  for (const row of dataset.rows) {\n    teamSheet.addRow([\n      row.rank ?? "—",\n      row.name || "—",\n      row.department || "—",\n      row.performanceScore ?? "—",\n      row.scoreConfidence || "—",\n      row.completedTasks || 0,\n      row.totalTasks || 0,\n      `${row.completionRate || 0}%`,\n      Number(row.actualHours || 0),\n      row.overdueTasks || 0,\n      row.trend?.label || "—",\n      row.status || "No Activity",\n    ]);\n  }\n\n  const taskSheet = workbook.addWorksheet("Task Details");\n  taskSheet.addRow(["Employee", "Task", "Project", "Status", "Priority", "Estimated Hours", "Actual Hours", "Due Date", "Completed At"]);\n  const userNameById = new Map(dataset.rows.map((item) => [item.id, item.name]));\n  for (const task of dataset.tasks) {\n    taskSheet.addRow([\n      userNameById.get(task.assigneeId) || "—",\n      task.title || "—",\n      task.project?.name || "—",\n      task.status || "—",\n      task.priority || "—",\n      Number(task.estimatedHours || 0),\n      Number(task.actualHours || 0),\n      task.dueDate ? task.dueDate.toISOString().slice(0, 10) : "—",\n      task.completedAt ? task.completedAt.toISOString().slice(0, 10) : "—",\n    ]);\n  }\n\n  const scoreSheet = workbook.addWorksheet("Score Breakdown");\n  scoreSheet.addRow(["Employee", "Completion", "On-Time", "Efficiency", "Workflow", "Consistency", "Final Score", "Confidence"]);\n  for (const row of dataset.rows) {\n    const breakdown = row.scoreBreakdown || {};\n    scoreSheet.addRow([\n      row.name || "—",\n      breakdownCell(breakdown.completion),\n      breakdownCell(breakdown.onTime),\n      breakdownCell(breakdown.efficiency),\n      breakdownCell(breakdown.workflow),\n      breakdownCell(breakdown.consistency),\n      row.performanceScore ?? "—",\n      row.scoreConfidence || "—",\n    ]);\n  }\n\n  for (const sheet of [teamSheet, taskSheet, scoreSheet]) {\n    sheet.views = [{ state: "frozen", ySplit: 1 }];\n    sheet.getRow(1).font = { bold: true };\n    sheet.getRow(1).height = 22;\n    sheet.autoFilter = { from: { row: 1, column: 1 }, to: { row: 1, column: sheet.columnCount } };\n    sheet.columns.forEach((column) => { column.width = Math.max(14, Math.min(42, column.width || 14)); });\n  }\n\n  const filename = teamPerformanceExportFilename("xlsx", dataset.filters.periodStart, dataset.filters.periodEnd);\n  const buffer = await workbook.xlsx.writeBuffer();\n\n  await prisma.workspaceAuditLog.create({\n    data: {\n      action: "team_performance_exported",\n      actorId: req.user.id,\n      metadata: {\n        reportType: "team_performance",\n        format: "excel",\n        ...dataset.filters,\n        filename,\n        rowCount: dataset.rows.length,\n        taskCount: dataset.tasks.length,\n        exportedAt: new Date().toISOString(),\n      },\n    },\n  });\n\n  res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");\n  res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);\n  res.send(Buffer.from(buffer));\n}));\n\nrouter.post("/reports/team-performance/export/pdf", asyncHandler(async (req, res) => {\n  const dataset = await buildTeamPerformanceExportDataset(req, req.body);\n  const filename = teamPerformanceExportFilename("pdf", dataset.filters.periodStart, dataset.filters.periodEnd);\n  const doc = new PDFDocument({ margin: 40, size: "A4" });\n  const chunks = [];\n  const completedBuffer = new Promise((resolve, reject) => {\n    doc.on("data", (chunk) => chunks.push(chunk));\n    doc.on("end", () => resolve(Buffer.concat(chunks)));\n    doc.on("error", reject);\n  });\n\n  doc.font("Helvetica-Bold").fontSize(20).text("TOS Team Performance", { align: "center" });\n  doc.moveDown(0.35);\n  doc.font("Helvetica").fontSize(9).fillColor("#666666")\n    .text(`Period: ${dataset.filters.periodStart.slice(0, 10)} to ${dataset.filters.periodEnd.slice(0, 10)}`, { align: "center" })\n    .text(`Generated: ${new Date().toISOString()}  |  By: ${req.user.name || req.user.email || req.user.id}`, { align: "center" });\n  doc.fillColor("#000000").moveDown(1);\n\n  doc.font("Helvetica-Bold").fontSize(12).text("Management Summary");\n  doc.font("Helvetica").fontSize(10).moveDown(0.3);\n  doc.text(`Average Score: ${dataset.summary.avgScore ?? "N/A"}`);\n  doc.text(`Top Performer: ${dataset.summary.topPerformer ? `${dataset.summary.topPerformer.name} (${dataset.summary.topPerformer.performanceScore})` : "N/A"}`);\n  doc.text(`Completed Tasks: ${dataset.summary.completedTasks}/${dataset.summary.totalTasks} (${dataset.summary.completionRate}%)`);\n  doc.text(`Overdue Tasks: ${dataset.summary.overdueTasks}`);\n  doc.text(`Logged Hours: ${dataset.summary.actualHours}h`);\n  doc.moveDown(0.8);\n\n  doc.font("Helvetica-Bold").fontSize(12).text("Team Performance");\n  doc.moveDown(0.35);\n  for (const row of dataset.rows) {\n    if (doc.y > 735) doc.addPage();\n    doc.font("Helvetica-Bold").fontSize(9).fillColor("#111111")\n      .text(`${row.rank ? `#${row.rank}` : "—"}  ${row.name || "Unknown"}`, { continued: true, width: 250 });\n    doc.font("Helvetica").fillColor("#444444")\n      .text(`  Score ${row.performanceScore ?? "—"}  |  ${row.completedTasks}/${row.totalTasks} done  |  ${row.actualHours || 0}h  |  overdue ${row.overdueTasks || 0}  |  ${row.status || "No Activity"}`);\n    doc.moveDown(0.3);\n  }\n\n  const attention = dataset.rows.filter((row) => row.performanceScore != null && row.performanceScore < 70);\n  if (attention.length) {\n    if (doc.y > 650) doc.addPage();\n    doc.moveDown(0.8).font("Helvetica-Bold").fontSize(12).fillColor("#000000").text("Employees Needing Attention");\n    doc.font("Helvetica").fontSize(9);\n    for (const row of attention) {\n      doc.text(`• ${row.name}: ${row.performanceScore} — ${row.status}`);\n    }\n  }\n\n  doc.end();\n  const buffer = await completedBuffer;\n\n  await prisma.workspaceAuditLog.create({\n    data: {\n      action: "team_performance_exported",\n      actorId: req.user.id,\n      metadata: {\n        reportType: "team_performance",\n        format: "pdf",\n        ...dataset.filters,\n        filename,\n        rowCount: dataset.rows.length,\n        exportedAt: new Date().toISOString(),\n      },\n    },\n  });\n\n  res.setHeader("Content-Type", "application/pdf");\n  res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);\n  res.send(buffer);\n}));'
FRONTEND_SOURCE = 'import { useEffect, useMemo, useState } from "react";\nimport {\n  AlertCircle,\n  BarChart3,\n  BriefcaseBusiness,\n  CalendarDays,\n  CheckCircle2,\n  ChevronDown,\n  Clock3,\n  Download,\n  FileSpreadsheet,\n  FileText,\n  RefreshCw,\n  Search,\n  ShieldCheck,\n  TrendingDown,\n  TrendingUp,\n  UserRound,\n  UsersRound,\n  X,\n} from "lucide-react";\nimport { Badge, Card, Notice, PageIntro } from "../components/ui/Primitives";\nimport { usePreferences } from "../contexts/PreferencesContext";\nimport { useT } from "../i18n/translations";\nimport { api } from "../lib/api";\nimport { getErrorMessage } from "../lib/errors";\nimport { useRealtimeVersion } from "../lib/realtimeStateSync";\n\nconst TEAM_PRESETS = [\n  { key: "today", label: "Today" },\n  { key: "yesterday", label: "Yesterday" },\n  { key: "week", label: "Week" },\n  { key: "month", label: "Month" },\n  { key: "year", label: "Year" },\n  { key: "custom", label: "Custom" },\n];\n\nconst STATUS_FILTERS = ["All", "Excellent", "On Track", "Needs Attention", "At Risk", "No Activity"];\n\nfunction startOfDay(date = new Date()) {\n  const next = new Date(date);\n  next.setHours(0, 0, 0, 0);\n  return next;\n}\n\nfunction endOfDay(date = new Date()) {\n  const next = new Date(date);\n  next.setHours(23, 59, 59, 999);\n  return next;\n}\n\nfunction parseDateInput(value, boundary = "start") {\n  if (!value) return null;\n  const parsed = new Date(`${value}T00:00:00`);\n  if (Number.isNaN(parsed.getTime())) return null;\n  return boundary === "end" ? endOfDay(parsed) : startOfDay(parsed);\n}\n\nfunction getTeamDateRange(preset, customStart, customEnd) {\n  const now = new Date();\n  let start = null;\n  let end = null;\n\n  if (preset === "today") {\n    start = startOfDay(now);\n    end = endOfDay(now);\n  } else if (preset === "yesterday") {\n    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);\n    start = startOfDay(d);\n    end = endOfDay(d);\n  } else if (preset === "week") {\n    const day = now.getDay() || 7;\n    start = startOfDay(new Date(now.getFullYear(), now.getMonth(), now.getDate() - day + 1));\n    end = endOfDay(now);\n  } else if (preset === "month") {\n    start = startOfDay(new Date(now.getFullYear(), now.getMonth(), 1));\n    end = endOfDay(now);\n  } else if (preset === "year") {\n    start = startOfDay(new Date(now.getFullYear(), 0, 1));\n    end = endOfDay(now);\n  } else if (preset === "custom") {\n    start = parseDateInput(customStart, "start");\n    end = parseDateInput(customEnd, "end");\n  }\n\n  return {\n    start,\n    end,\n    invalid: Boolean(start && end && start > end),\n  };\n}\n\nfunction formatHours(value) {\n  const hours = Number(value || 0);\n  if (!Number.isFinite(hours) || hours <= 0) return "0h";\n  if (hours < 1) return `${Math.round(hours * 60)}m`;\n  return `${Math.round(hours * 10) / 10}h`;\n}\n\nfunction formatDate(value) {\n  if (!value) return "—";\n  try {\n    return new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(value));\n  } catch {\n    return "—";\n  }\n}\n\nfunction scoreTextClass(score) {\n  if (score == null) return "text-zinc-400";\n  if (score >= 85) return "text-emerald-600 dark:text-emerald-400";\n  if (score >= 70) return "text-amber-600 dark:text-amber-300";\n  if (score >= 50) return "text-orange-600 dark:text-orange-300";\n  return "text-red-600 dark:text-red-400";\n}\n\nfunction statusClasses(status) {\n  if (status === "Excellent") return "bg-emerald-50 text-emerald-700 ring-emerald-200 dark:bg-emerald-400/10 dark:text-emerald-300 dark:ring-emerald-400/20";\n  if (status === "On Track") return "bg-amber-50 text-amber-700 ring-amber-200 dark:bg-amber-400/10 dark:text-amber-300 dark:ring-amber-400/20";\n  if (status === "Needs Attention") return "bg-orange-50 text-orange-700 ring-orange-200 dark:bg-orange-400/10 dark:text-orange-300 dark:ring-orange-400/20";\n  if (status === "At Risk") return "bg-red-50 text-red-700 ring-red-200 dark:bg-red-400/10 dark:text-red-300 dark:ring-red-400/20";\n  return "bg-zinc-100 text-zinc-600 ring-zinc-200 dark:bg-white/10 dark:text-zinc-300 dark:ring-white/10";\n}\n\nfunction StatusBadge({ status }) {\n  return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-black ring-1 ring-inset ${statusClasses(status)}`}>{status || "No Activity"}</span>;\n}\n\nfunction TrendValue({ trend }) {\n  const delta = trend?.scoreDelta;\n  if (delta == null) return <span className="text-zinc-400">{trend?.label || "—"}</span>;\n  if (delta > 0) return <span className="inline-flex items-center gap-1 font-black text-emerald-600 dark:text-emerald-400"><TrendingUp size={13} />+{delta}</span>;\n  if (delta < 0) return <span className="inline-flex items-center gap-1 font-black text-red-600 dark:text-red-400"><TrendingDown size={13} />{delta}</span>;\n  return <span className="font-black text-zinc-400">—</span>;\n}\n\nfunction activityLabel(activity) {\n  const action = String(activity?.metadata?.action || "").trim();\n  const actionLabels = {\n    task_started: "Started task",\n    task_sent_to_review: "Sent to review",\n    task_completed: "Completed task",\n    task_hours_updated: "Updated task hours",\n    task_status_changed: "Changed task status",\n  };\n  if (actionLabels[action]) return actionLabels[action];\n  const typeLabels = {\n    CREATED: "Created task",\n    UPDATED: "Updated task",\n    STATUS_CHANGED: "Changed task status",\n    PROGRESS_CHANGED: "Updated task progress",\n    PRIORITY_CHANGED: "Changed task priority",\n    LIST_CHANGED: "Moved task",\n    BOARD_CHANGED: "Moved task board",\n    COMPLETED: "Completed task",\n    REOPENED: "Reopened task",\n    ARCHIVED: "Archived task",\n    RESTORED: "Restored task",\n  };\n  return typeLabels[activity?.type] || "Task activity";\n}\n\nfunction KpiCard({ icon: Icon, label, value, note = "", tone = "neutral" }) {\n  const shell = {\n    neutral: "border-zinc-200 bg-white dark:border-white/10 dark:bg-white/[0.035]",\n    green: "border-emerald-200/80 bg-emerald-50/70 dark:border-emerald-400/15 dark:bg-emerald-400/[0.07]",\n    gold: "border-amber-200/80 bg-amber-50/70 dark:border-amber-400/15 dark:bg-amber-400/[0.07]",\n    red: "border-red-200/80 bg-red-50/70 dark:border-red-400/15 dark:bg-red-400/[0.07]",\n  }[tone];\n  return (\n    <div className={`rounded-2xl border p-4 ${shell}`}>\n      <div className="flex items-center justify-between gap-3">\n        <p className="text-[11px] font-black uppercase tracking-[0.08em] text-zinc-400">{label}</p>\n        <Icon size={17} className="text-zinc-500 dark:text-zinc-300" />\n      </div>\n      <p className="mt-2 text-2xl font-black text-zinc-950 dark:text-white">{value}</p>\n      {note ? <p className="mt-1 text-[11px] font-bold text-zinc-400">{note}</p> : null}\n    </div>\n  );\n}\n\nfunction ScorePopover({ employee }) {\n  const [open, setOpen] = useState(false);\n  if (employee.performanceScore == null) return <span className="font-black text-zinc-400">—</span>;\n  return (\n    <div className="relative inline-flex items-center">\n      <button\n        type="button"\n        onClick={(event) => { event.stopPropagation(); setOpen((value) => !value); }}\n        className={`rounded-lg px-2 py-1 text-lg font-black outline-none ring-amber-400 focus-visible:ring-2 ${scoreTextClass(employee.performanceScore)}`}\n        aria-label={`Performance score ${employee.performanceScore}. Show score breakdown`}\n        aria-expanded={open}\n      >\n        {employee.performanceScore}\n      </button>\n      {open ? (\n        <div className="absolute right-0 top-full z-40 mt-2 w-64 rounded-2xl border border-zinc-200 bg-white p-3.5 text-left shadow-2xl dark:border-white/10 dark:bg-zinc-950" onClick={(event) => event.stopPropagation()}>\n          <div className="flex items-center justify-between">\n            <p className="text-xs font-black text-zinc-950 dark:text-white">Score breakdown</p>\n            <span className="text-[10px] font-black text-zinc-400">Confidence: {employee.scoreConfidence || "Low"}</span>\n          </div>\n          <div className="mt-3 space-y-2">\n            {Object.entries(employee.scoreBreakdown || {}).map(([key, value]) => (\n              <div key={key}>\n                <div className="flex items-center justify-between text-[11px]">\n                  <span className="font-bold capitalize text-zinc-500">{key}</span>\n                  <span className="font-black text-zinc-900 dark:text-white">\n                    {value?.skipped ? "Skipped" : `${value?.achieved ?? 0}/${value?.max ?? 0}`}\n                  </span>\n                </div>\n                <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-zinc-100 dark:bg-white/10">\n                  <div className="h-full rounded-full bg-amber-400" style={{ width: `${value?.skipped || !value?.max ? 0 : Math.min(100, (Number(value.achieved || 0) / Number(value.max || 1)) * 100)}%` }} />\n                </div>\n              </div>\n            ))}\n          </div>\n        </div>\n      ) : null}\n    </div>\n  );\n}\n\nfunction HistoryChart({ data = [] }) {\n  const points = data.filter((item) => item.performanceScore != null);\n  if (!points.length) return <div className="rounded-xl border border-dashed border-zinc-200 p-5 text-center text-xs font-bold text-zinc-400 dark:border-white/10">No score history for this period.</div>;\n\n  const width = 520;\n  const height = 150;\n  const padX = 18;\n  const padY = 16;\n  const coords = points.map((item, index) => {\n    const x = points.length === 1 ? width / 2 : padX + (index * (width - padX * 2)) / (points.length - 1);\n    const y = height - padY - (Number(item.performanceScore) / 100) * (height - padY * 2);\n    return { ...item, x, y };\n  });\n  const polyline = coords.map((point) => `${point.x},${point.y}`).join(" ");\n\n  return (\n    <div className="overflow-hidden rounded-xl border border-zinc-100 bg-zinc-50/70 p-2 dark:border-white/10 dark:bg-white/[0.025]">\n      <svg viewBox={`0 0 ${width} ${height}`} className="h-36 w-full" role="img" aria-label="Performance score history">\n        {[25, 50, 75, 100].map((score) => {\n          const y = height - padY - (score / 100) * (height - padY * 2);\n          return <line key={score} x1={padX} x2={width - padX} y1={y} y2={y} stroke="currentColor" className="text-zinc-200 dark:text-zinc-800" strokeWidth="1" />;\n        })}\n        <polyline points={polyline} fill="none" stroke="currentColor" className="text-amber-500" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />\n        {coords.map((point, index) => <circle key={`${point.label}-${index}`} cx={point.x} cy={point.y} r="4" fill="currentColor" className="text-amber-500" />)}\n      </svg>\n      <div className="mt-1 grid gap-1 text-[9px] font-bold text-zinc-400" style={{ gridTemplateColumns: `repeat(${Math.min(points.length, 8)}, minmax(0,1fr))` }}>\n        {points.slice(-8).map((point, index) => <span key={`${point.label}-label-${index}`} className="truncate text-center">{point.label}</span>)}\n      </div>\n    </div>\n  );\n}\n\nfunction historyRange(preset, selectedRange) {\n  const end = selectedRange?.end ? new Date(selectedRange.end) : endOfDay(new Date());\n  if (preset === "today" || preset === "yesterday") {\n    const start = startOfDay(new Date(end.getFullYear(), end.getMonth(), end.getDate() - 6));\n    return { start, end, granularity: "day" };\n  }\n  if (preset === "week") {\n    const day = end.getDay() || 7;\n    const monday = startOfDay(new Date(end.getFullYear(), end.getMonth(), end.getDate() - day + 1));\n    const start = new Date(monday);\n    start.setDate(start.getDate() - 49);\n    return { start, end, granularity: "week" };\n  }\n  if (preset === "month") {\n    return { start: startOfDay(new Date(end.getFullYear(), end.getMonth() - 5, 1)), end, granularity: "month" };\n  }\n  if (preset === "year") {\n    return { start: startOfDay(new Date(end.getFullYear(), end.getMonth() - 11, 1)), end, granularity: "month" };\n  }\n\n  const start = selectedRange?.start ? new Date(selectedRange.start) : startOfDay(new Date(end.getFullYear(), end.getMonth() - 5, 1));\n  const days = Math.max(1, Math.ceil((end - start) / 86400000));\n  const granularity = days <= 14 ? "day" : days <= 90 ? "week" : "month";\n  return { start, end, granularity };\n}\n\nfunction triggerDownload(result) {\n  const url = URL.createObjectURL(result.blob);\n  const anchor = document.createElement("a");\n  anchor.href = url;\n  anchor.download = result.filename || "TOS_Team_Performance";\n  document.body.appendChild(anchor);\n  anchor.click();\n  anchor.remove();\n  setTimeout(() => URL.revokeObjectURL(url), 4000);\n}\n\nexport function TeamPerformanceDashboard({ user, onOpenTask = null }) {\n  const { lang } = usePreferences();\n  const tr = useT(lang);\n  const t = tr.teamPerformance;\n  const firstName = user?.name?.split(" ")?.[0] || user?.name || user?.email || "";\n\n  const [preset, setPreset] = useState("month");\n  const [customStart, setCustomStart] = useState("");\n  const [customEnd, setCustomEnd] = useState("");\n  const [employeeFilter, setEmployeeFilter] = useState("all");\n  const [departmentFilter, setDepartmentFilter] = useState("all");\n  const [statusFilter, setStatusFilter] = useState("All");\n  const [searchTerm, setSearchTerm] = useState("");\n  const [sortBy, setSortBy] = useState("score");\n  const [sortDirection, setSortDirection] = useState("desc");\n\n  const [teamData, setTeamData] = useState(null);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState("");\n  const [refreshNonce, setRefreshNonce] = useState(0);\n\n  const [selectedEmployeeId, setSelectedEmployeeId] = useState(null);\n  const [drawerOpen, setDrawerOpen] = useState(false);\n  const [drawerTasks, setDrawerTasks] = useState([]);\n  const [drawerActivities, setDrawerActivities] = useState([]);\n  const [activityPage, setActivityPage] = useState(1);\n  const [activityTotal, setActivityTotal] = useState(0);\n  const [drawerHistory, setDrawerHistory] = useState([]);\n  const [drawerLoading, setDrawerLoading] = useState(false);\n\n  const [exportMenuOpen, setExportMenuOpen] = useState(false);\n  const [exporting, setExporting] = useState("");\n  const [toast, setToast] = useState(null);\n\n  const selectedRange = useMemo(() => getTeamDateRange(preset, customStart, customEnd), [preset, customStart, customEnd]);\n  const realtimeRefreshVersion = useRealtimeVersion(["tasks", "teamPerformance", "projects", "users"], { debounceMs: 500, minIntervalMs: 1000 });\n\n  useEffect(() => {\n    if (!selectedRange.start || !selectedRange.end || selectedRange.invalid) return;\n    let ignore = false;\n    async function load() {\n      setLoading(true);\n      setError("");\n      try {\n        const data = await api.tasks.teamPerformance({\n          start: selectedRange.start.toISOString(),\n          end: selectedRange.end.toISOString(),\n        });\n        if (!ignore) setTeamData(data);\n      } catch (err) {\n        if (!ignore) {\n          setTeamData(null);\n          setError(getErrorMessage(err, "Unable to load team performance. Try again."));\n        }\n      } finally {\n        if (!ignore) setLoading(false);\n      }\n    }\n    load();\n    return () => { ignore = true; };\n  }, [selectedRange.start?.getTime(), selectedRange.end?.getTime(), selectedRange.invalid, refreshNonce, realtimeRefreshVersion]);\n\n  const allEmployees = teamData?.byUser || [];\n  const departments = useMemo(() => Array.from(new Set(allEmployees.map((employee) => employee.department).filter(Boolean))).sort(), [allEmployees]);\n\n  const filteredEmployees = useMemo(() => {\n    const term = searchTerm.trim().toLowerCase();\n    let rows = allEmployees.filter((employee) => {\n      if (employeeFilter !== "all" && employee.id !== employeeFilter) return false;\n      if (departmentFilter !== "all" && (employee.department || "") !== departmentFilter) return false;\n      if (statusFilter !== "All" && (employee.status || "No Activity") !== statusFilter) return false;\n      if (term && !`${employee.name || ""} ${employee.email || ""} ${employee.jobTitle || ""} ${employee.department || ""}`.toLowerCase().includes(term)) return false;\n      return true;\n    });\n\n    rows = [...rows].sort((a, b) => {\n      const direction = sortDirection === "asc" ? 1 : -1;\n      if (sortBy === "score") {\n        if (a.performanceScore == null && b.performanceScore == null) return (a.name || "").localeCompare(b.name || "");\n        if (a.performanceScore == null) return 1;\n        if (b.performanceScore == null) return -1;\n        return (a.performanceScore - b.performanceScore) * direction;\n      }\n      const keys = {\n        completed: "completedTasks",\n        hours: "actualHours",\n        overdue: "overdueTasks",\n      };\n      const key = keys[sortBy];\n      if (!key) return 0;\n      return (Number(a[key] || 0) - Number(b[key] || 0)) * direction;\n    });\n    return rows;\n  }, [allEmployees, employeeFilter, departmentFilter, statusFilter, searchTerm, sortBy, sortDirection]);\n\n  const filteredRankMap = useMemo(() => {\n    const ranked = filteredEmployees.filter((employee) => employee.performanceScore != null).sort((a, b) => b.performanceScore - a.performanceScore);\n    return new Map(ranked.map((employee, index) => [employee.id, index + 1]));\n  }, [filteredEmployees]);\n\n  const filteredSummary = useMemo(() => {\n    const scored = filteredEmployees.filter((employee) => employee.performanceScore != null);\n    const avgScore = scored.length ? Math.round((scored.reduce((sum, employee) => sum + Number(employee.performanceScore || 0), 0) / scored.length) * 10) / 10 : null;\n    const top = [...scored].sort((a, b) => b.performanceScore - a.performanceScore)[0] || null;\n    const completed = filteredEmployees.reduce((sum, employee) => sum + Number(employee.completedTasks || 0), 0);\n    const total = filteredEmployees.reduce((sum, employee) => sum + Number(employee.totalTasks || 0), 0);\n    const overdue = filteredEmployees.reduce((sum, employee) => sum + Number(employee.overdueTasks || 0), 0);\n    const hours = filteredEmployees.reduce((sum, employee) => sum + Number(employee.actualHours || 0), 0);\n    return { avgScore, top, completed, total, overdue, hours, completionRate: total ? Math.round((completed / total) * 100) : 0 };\n  }, [filteredEmployees]);\n\n  const selectedEmployee = allEmployees.find((employee) => employee.id === selectedEmployeeId) || null;\n\n  function changeSort(next) {\n    if (sortBy === next) setSortDirection((direction) => direction === "asc" ? "desc" : "asc");\n    else {\n      setSortBy(next);\n      setSortDirection(next === "overdue" ? "desc" : "desc");\n    }\n  }\n\n  async function loadDrawer(employee, page = 1, appendActivities = false) {\n    if (!employee || !selectedRange.start || !selectedRange.end) return;\n    setDrawerLoading(true);\n    try {\n      const history = historyRange(preset, selectedRange);\n      const [taskPayload, activityPayload, historyPayload] = await Promise.all([\n        api.tasks.userDashboard({\n          userId: employee.id,\n          start: selectedRange.start.toISOString(),\n          end: selectedRange.end.toISOString(),\n        }),\n        api.tasks.activities({\n          employeeId: employee.id,\n          startDate: selectedRange.start.toISOString(),\n          endDate: selectedRange.end.toISOString(),\n          page,\n          limit: 30,\n        }),\n        api.tasks.teamPerformanceHistory({\n          employeeId: employee.id,\n          startDate: history.start.toISOString(),\n          endDate: history.end.toISOString(),\n          granularity: history.granularity,\n        }),\n      ]);\n      setDrawerTasks(taskPayload?.tasks || []);\n      setDrawerActivities((current) => appendActivities ? [...current, ...(activityPayload?.activities || [])] : (activityPayload?.activities || []));\n      setActivityPage(page);\n      setActivityTotal(Number(activityPayload?.pagination?.total || 0));\n      setDrawerHistory(historyPayload?.history || []);\n    } catch (err) {\n      setToast({ type: "error", message: getErrorMessage(err, "Unable to load employee details.") });\n    } finally {\n      setDrawerLoading(false);\n    }\n  }\n\n  async function openEmployee(employeeId) {\n    const employee = allEmployees.find((item) => item.id === employeeId);\n    if (!employee) return;\n    setSelectedEmployeeId(employeeId);\n    setDrawerOpen(true);\n    setDrawerTasks([]);\n    setDrawerActivities([]);\n    setDrawerHistory([]);\n    await loadDrawer(employee, 1, false);\n  }\n\n  async function exportReport(format) {\n    if (!selectedRange.start || !selectedRange.end || selectedRange.invalid) return;\n    setExporting(format);\n    setExportMenuOpen(false);\n    try {\n      const result = await api.tasks.exportTeamPerformance(format, {\n        start: selectedRange.start.toISOString(),\n        end: selectedRange.end.toISOString(),\n        employeeId: employeeFilter !== "all" ? employeeFilter : null,\n        department: departmentFilter !== "all" ? departmentFilter : null,\n        status: statusFilter !== "All" ? statusFilter : null,\n        search: searchTerm.trim() || null,\n      });\n      triggerDownload(result);\n      setToast({ type: "success", message: `${format.toUpperCase()} report generated.` });\n    } catch (err) {\n      setToast({ type: "error", message: getErrorMessage(err, "Unable to export team performance.") });\n    } finally {\n      setExporting("");\n    }\n  }\n\n  const periodLabel = selectedRange.start && selectedRange.end\n    ? `${formatDate(selectedRange.start)} — ${formatDate(selectedRange.end)}`\n    : "Choose a valid period";\n\n  return (\n    <div className="tos-page space-y-4">\n      <PageIntro\n        eyebrow={t?.eyebrow || "TEAM PERFORMANCE"}\n        title={t?.title || "Team Performance"}\n        description={`Management view for team score, delivery, overdue work and time. ${firstName ? `Welcome ${firstName}.` : ""}`}\n        actions={<Badge tone="success"><ShieldCheck size={14} /> Live data</Badge>}\n      />\n\n      <Card className="p-4">\n        <div className="flex flex-col gap-3">\n          <div className="flex flex-wrap items-center gap-2">\n            {TEAM_PRESETS.map((item) => (\n              <button\n                key={item.key}\n                type="button"\n                onClick={() => setPreset(item.key)}\n                className={`rounded-xl border px-3 py-2 text-xs font-black transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400 ${preset === item.key ? "border-amber-300 bg-amber-50 text-amber-700 dark:border-amber-400/30 dark:bg-amber-400/10 dark:text-amber-200" : "border-zinc-200 bg-white text-zinc-600 hover:border-amber-300 dark:border-white/10 dark:bg-white/[0.03] dark:text-zinc-300"}`}\n              >\n                {item.label}\n              </button>\n            ))}\n            <span className="ml-auto text-[11px] font-bold text-zinc-400">{periodLabel}</span>\n          </div>\n\n          {preset === "custom" ? (\n            <div className="grid gap-2 sm:grid-cols-2 lg:max-w-md">\n              <input type="date" value={customStart} onChange={(event) => setCustomStart(event.target.value)} className="rounded-xl border border-zinc-200 bg-white px-3 py-2 text-xs font-bold outline-none focus:border-amber-400 dark:border-white/10 dark:bg-zinc-900 dark:text-white" aria-label="Custom period start" />\n              <input type="date" value={customEnd} onChange={(event) => setCustomEnd(event.target.value)} className="rounded-xl border border-zinc-200 bg-white px-3 py-2 text-xs font-bold outline-none focus:border-amber-400 dark:border-white/10 dark:bg-zinc-900 dark:text-white" aria-label="Custom period end" />\n            </div>\n          ) : null}\n\n          <div className="grid gap-2 md:grid-cols-2 xl:grid-cols-[1fr_1fr_1.2fr_auto_auto]">\n            <select value={employeeFilter} onChange={(event) => setEmployeeFilter(event.target.value)} className="min-h-10 rounded-xl border border-zinc-200 bg-white px-3 text-xs font-bold text-zinc-800 outline-none focus:border-amber-400 dark:border-white/10 dark:bg-zinc-900 dark:text-white" aria-label="Employee filter">\n              <option value="all">All employees</option>\n              {allEmployees.map((employee) => <option key={employee.id} value={employee.id}>{employee.name}</option>)}\n            </select>\n            <select value={departmentFilter} onChange={(event) => setDepartmentFilter(event.target.value)} className="min-h-10 rounded-xl border border-zinc-200 bg-white px-3 text-xs font-bold text-zinc-800 outline-none focus:border-amber-400 dark:border-white/10 dark:bg-zinc-900 dark:text-white" aria-label="Department filter">\n              <option value="all">All departments</option>\n              {departments.map((department) => <option key={department} value={department}>{department}</option>)}\n            </select>\n            <label className="flex min-h-10 items-center gap-2 rounded-xl border border-zinc-200 bg-white px-3 dark:border-white/10 dark:bg-zinc-900">\n              <Search size={15} className="text-zinc-400" />\n              <input value={searchTerm} onChange={(event) => setSearchTerm(event.target.value)} placeholder="Search employee…" className="w-full bg-transparent text-xs font-bold text-zinc-800 outline-none placeholder:text-zinc-400 dark:text-white" />\n            </label>\n            <button type="button" onClick={() => setRefreshNonce((value) => value + 1)} disabled={loading} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-zinc-200 bg-white px-3 text-xs font-black text-zinc-700 hover:border-amber-300 disabled:opacity-50 dark:border-white/10 dark:bg-white/[0.03] dark:text-zinc-200">\n              <RefreshCw size={15} className={loading ? "animate-spin" : ""} /> Refresh\n            </button>\n            <div className="relative">\n              <button type="button" onClick={() => setExportMenuOpen((value) => !value)} disabled={Boolean(exporting)} className="inline-flex min-h-10 w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-l from-amber-500 to-yellow-300 px-4 text-xs font-black text-zinc-950 shadow-sm disabled:opacity-60" aria-expanded={exportMenuOpen}>\n                <Download size={15} /> {exporting ? "Exporting…" : "Export"} <ChevronDown size={14} />\n              </button>\n              {exportMenuOpen ? (\n                <div className="absolute right-0 top-full z-40 mt-2 w-44 rounded-xl border border-zinc-200 bg-white p-1.5 shadow-xl dark:border-white/10 dark:bg-zinc-950">\n                  <button type="button" onClick={() => exportReport("excel")} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-xs font-black text-zinc-700 hover:bg-zinc-50 dark:text-zinc-200 dark:hover:bg-white/5"><FileSpreadsheet size={15} /> Excel</button>\n                  <button type="button" onClick={() => exportReport("pdf")} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-xs font-black text-zinc-700 hover:bg-zinc-50 dark:text-zinc-200 dark:hover:bg-white/5"><FileText size={15} /> PDF</button>\n                </div>\n              ) : null}\n            </div>\n          </div>\n        </div>\n      </Card>\n\n      {selectedRange.invalid ? <Notice type="error">Custom start date must be before the end date.</Notice> : null}\n      {error ? <Notice type="error">{error}</Notice> : null}\n      {toast ? <Notice type={toast.type === "success" ? "success" : "error"}>{toast.message}</Notice> : null}\n\n      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">\n        <KpiCard icon={BarChart3} label="Average score" value={filteredSummary.avgScore ?? "—"} note={`${filteredEmployees.filter((employee) => employee.performanceScore != null).length} scored employees`} tone="gold" />\n        <KpiCard icon={UserRound} label="Top performer" value={filteredSummary.top?.name || "—"} note={filteredSummary.top ? `Score ${filteredSummary.top.performanceScore}` : "No scored employees"} tone="green" />\n        <KpiCard icon={CheckCircle2} label="Completed tasks" value={`${filteredSummary.completed}/${filteredSummary.total}`} note={`${filteredSummary.completionRate}% completion`} tone="green" />\n        <KpiCard icon={AlertCircle} label="Overdue tasks" value={filteredSummary.overdue} note="Within selected team scope" tone="red" />\n        <KpiCard icon={Clock3} label="Logged hours" value={formatHours(filteredSummary.hours)} note="Actual task hours" tone="neutral" />\n      </div>\n\n      <Card className="overflow-hidden p-0">\n        <div className="flex flex-col gap-3 border-b border-zinc-100 p-4 dark:border-white/10 lg:flex-row lg:items-center lg:justify-between">\n          <div>\n            <p className="text-[11px] font-black uppercase tracking-[0.1em] text-amber-500">Management view</p>\n            <h2 className="mt-1 text-base font-black text-zinc-950 dark:text-white">Team Performance</h2>\n          </div>\n          <div className="flex flex-wrap gap-1.5">\n            {STATUS_FILTERS.map((status) => (\n              <button key={status} type="button" onClick={() => setStatusFilter(status)} className={`rounded-full px-3 py-1.5 text-[11px] font-black transition ${statusFilter === status ? "bg-zinc-950 text-white dark:bg-white dark:text-zinc-950" : "bg-zinc-100 text-zinc-500 hover:bg-zinc-200 dark:bg-white/[0.06] dark:text-zinc-300 dark:hover:bg-white/10"}`}>{status}</button>\n            ))}\n          </div>\n        </div>\n\n        {loading ? (\n          <div className="grid gap-2 p-4">\n            {[1, 2, 3, 4, 5].map((item) => <div key={item} className="h-14 animate-pulse rounded-xl bg-zinc-100 dark:bg-white/[0.05]" />)}\n          </div>\n        ) : filteredEmployees.length === 0 ? (\n          <div className="p-10 text-center">\n            <UsersRound size={28} className="mx-auto text-zinc-300" />\n            <p className="mt-3 text-sm font-black text-zinc-500">No performance activity was recorded for this period.</p>\n          </div>\n        ) : (\n          <>\n            <div className="hidden overflow-x-auto md:block">\n              <table className="w-full min-w-[900px] text-xs">\n                <thead className="sticky top-0 bg-zinc-50 text-zinc-500 dark:bg-zinc-900 dark:text-zinc-300">\n                  <tr>\n                    <th className="px-3 py-3 text-center font-black">Rank</th>\n                    <th className="px-3 py-3 text-left font-black">Employee</th>\n                    <th className="px-3 py-3 text-left font-black">Department</th>\n                    <th className="px-3 py-3 text-right font-black"><button type="button" onClick={() => changeSort("score")}>Score</button></th>\n                    <th className="px-3 py-3 text-right font-black"><button type="button" onClick={() => changeSort("completed")}>Completed</button></th>\n                    <th className="px-3 py-3 text-right font-black">Completion</th>\n                    <th className="px-3 py-3 text-right font-black"><button type="button" onClick={() => changeSort("hours")}>Hours</button></th>\n                    <th className="px-3 py-3 text-right font-black"><button type="button" onClick={() => changeSort("overdue")}>Overdue</button></th>\n                    <th className="px-3 py-3 text-right font-black">Trend</th>\n                    <th className="px-3 py-3 text-right font-black">Status</th>\n                  </tr>\n                </thead>\n                <tbody className="divide-y divide-zinc-100 dark:divide-white/10">\n                  {filteredEmployees.map((employee) => (\n                    <tr key={employee.id} tabIndex={0} role="button" onClick={() => openEmployee(employee.id)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") openEmployee(employee.id); }} className="cursor-pointer bg-white transition hover:bg-amber-50/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-amber-400 dark:bg-transparent dark:hover:bg-amber-400/[0.04]">\n                      <td className="px-3 py-3 text-center font-black text-zinc-500">{filteredRankMap.get(employee.id) ? `#${filteredRankMap.get(employee.id)}` : "—"}</td>\n                      <td className="px-3 py-3">\n                        <div className="flex items-center gap-2.5">\n                          {employee.avatarUrl ? <img src={employee.avatarUrl} alt="" className="h-9 w-9 rounded-full object-cover" /> : <div className="grid h-9 w-9 place-items-center rounded-full bg-zinc-100 font-black text-zinc-500 dark:bg-white/10">{(employee.name || "U").slice(0, 1)}</div>}\n                          <div><p className="font-black text-zinc-950 dark:text-white">{employee.name}</p><p className="text-[10px] font-bold text-zinc-400">{employee.jobTitle || employee.role}</p></div>\n                        </div>\n                      </td>\n                      <td className="px-3 py-3 text-zinc-500 dark:text-zinc-300">{employee.department || "—"}</td>\n                      <td className="px-3 py-3 text-right"><ScorePopover employee={employee} /></td>\n                      <td className="px-3 py-3 text-right font-black text-zinc-900 dark:text-white">{employee.completedTasks}/{employee.totalTasks}</td>\n                      <td className="px-3 py-3 text-right font-black text-zinc-700 dark:text-zinc-200">{employee.completionRate}%</td>\n                      <td className="px-3 py-3 text-right font-black text-zinc-700 dark:text-zinc-200">{formatHours(employee.actualHours)}</td>\n                      <td className={`px-3 py-3 text-right font-black ${employee.overdueTasks ? "text-red-600 dark:text-red-400" : "text-zinc-400"}`}>{employee.overdueTasks}</td>\n                      <td className="px-3 py-3 text-right"><TrendValue trend={employee.trend} /></td>\n                      <td className="px-3 py-3 text-right"><StatusBadge status={employee.status || "No Activity"} /></td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n\n            <div className="grid gap-2 p-3 md:hidden">\n              {filteredEmployees.map((employee) => (\n                <button key={employee.id} type="button" onClick={() => openEmployee(employee.id)} className="rounded-2xl border border-zinc-100 bg-white p-3 text-left shadow-sm dark:border-white/10 dark:bg-white/[0.025]">\n                  <div className="flex items-center justify-between gap-3">\n                    <div className="flex min-w-0 items-center gap-2.5">\n                      <div className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-zinc-100 font-black text-zinc-500 dark:bg-white/10">{(employee.name || "U").slice(0, 1)}</div>\n                      <div className="min-w-0"><p className="truncate text-xs font-black text-zinc-950 dark:text-white">{employee.name}</p><p className="truncate text-[10px] font-bold text-zinc-400">{employee.department || employee.jobTitle || "—"}</p></div>\n                    </div>\n                    <div className="text-right"><p className={`text-xl font-black ${scoreTextClass(employee.performanceScore)}`}>{employee.performanceScore ?? "—"}</p><p className="text-[10px] font-black text-zinc-400">{filteredRankMap.get(employee.id) ? `#${filteredRankMap.get(employee.id)}` : "Unranked"}</p></div>\n                  </div>\n                  <div className="mt-3 grid grid-cols-4 gap-2 text-center text-[10px]">\n                    <div><p className="text-zinc-400">Done</p><p className="font-black text-zinc-900 dark:text-white">{employee.completedTasks}/{employee.totalTasks}</p></div>\n                    <div><p className="text-zinc-400">Hours</p><p className="font-black text-zinc-900 dark:text-white">{formatHours(employee.actualHours)}</p></div>\n                    <div><p className="text-zinc-400">Overdue</p><p className="font-black text-red-600">{employee.overdueTasks}</p></div>\n                    <div><p className="text-zinc-400">Trend</p><TrendValue trend={employee.trend} /></div>\n                  </div>\n                </button>\n              ))}\n            </div>\n          </>\n        )}\n      </Card>\n\n      {drawerOpen && selectedEmployee ? (\n        <div className="fixed inset-0 z-50 flex justify-end" role="dialog" aria-modal="true" aria-label={`${selectedEmployee.name} performance details`}>\n          <button type="button" className="absolute inset-0 cursor-default bg-black/50" onClick={() => setDrawerOpen(false)} aria-label="Close employee details" />\n          <aside className="relative h-full w-full overflow-hidden bg-white shadow-2xl dark:bg-zinc-950 sm:max-w-2xl">\n            <div className="flex h-full flex-col">\n              <header className="border-b border-zinc-100 p-4 dark:border-white/10">\n                <div className="flex items-start justify-between gap-3">\n                  <div className="flex min-w-0 items-center gap-3">\n                    {selectedEmployee.avatarUrl ? <img src={selectedEmployee.avatarUrl} alt="" className="h-12 w-12 rounded-full object-cover" /> : <div className="grid h-12 w-12 place-items-center rounded-full bg-zinc-100 text-lg font-black text-zinc-500 dark:bg-white/10">{(selectedEmployee.name || "U").slice(0, 1)}</div>}\n                    <div className="min-w-0">\n                      <h2 className="truncate text-lg font-black text-zinc-950 dark:text-white">{selectedEmployee.name}</h2>\n                      <p className="text-xs font-bold text-zinc-400">{selectedEmployee.jobTitle || "—"} · {selectedEmployee.department || "—"}</p>\n                      <div className="mt-2 flex flex-wrap items-center gap-2">\n                        <StatusBadge status={selectedEmployee.status || "No Activity"} />\n                        <span className="text-[11px] font-black text-zinc-400">Rank {filteredRankMap.get(selectedEmployee.id) ? `#${filteredRankMap.get(selectedEmployee.id)}` : "—"}</span>\n                        <span className="text-[11px] font-black text-zinc-400">Confidence {selectedEmployee.scoreConfidence || "—"}</span>\n                      </div>\n                    </div>\n                  </div>\n                  <button type="button" onClick={() => setDrawerOpen(false)} className="rounded-xl p-2 text-zinc-400 hover:bg-zinc-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400 dark:hover:bg-white/10" aria-label="Close"><X size={20} /></button>\n                </div>\n              </header>\n\n              <div className="flex-1 overflow-y-auto p-4">\n                <div className="grid grid-cols-2 gap-2 sm:grid-cols-5">\n                  <KpiCard icon={BarChart3} label="Score" value={selectedEmployee.performanceScore ?? "—"} tone="gold" />\n                  <KpiCard icon={CheckCircle2} label="Completed" value={`${selectedEmployee.completedTasks}/${selectedEmployee.totalTasks}`} tone="green" />\n                  <KpiCard icon={Clock3} label="Hours" value={formatHours(selectedEmployee.actualHours)} />\n                  <KpiCard icon={AlertCircle} label="Overdue" value={selectedEmployee.overdueTasks} tone="red" />\n                  <KpiCard icon={TrendingUp} label="Previous" value={selectedEmployee.previous?.performanceScore ?? "—"} note={selectedEmployee.trend?.label || "—"} />\n                </div>\n\n                <section className="mt-4 rounded-2xl border border-zinc-100 p-4 dark:border-white/10">\n                  <div className="flex items-center justify-between"><h3 className="text-sm font-black text-zinc-950 dark:text-white">Score Breakdown</h3><span className={`text-2xl font-black ${scoreTextClass(selectedEmployee.performanceScore)}`}>{selectedEmployee.performanceScore ?? "—"}</span></div>\n                  <div className="mt-3 space-y-2.5">\n                    {Object.entries(selectedEmployee.scoreBreakdown || {}).map(([key, value]) => (\n                      <div key={key}>\n                        <div className="flex items-center justify-between text-xs">\n                          <span className="font-black capitalize text-zinc-500">{key}</span>\n                          <span className="font-black text-zinc-900 dark:text-white">{value?.skipped ? "Skipped" : `${value?.achieved ?? 0}/${value?.max ?? 0}`}</span>\n                        </div>\n                        <div className="mt-1.5 h-2 overflow-hidden rounded-full bg-zinc-100 dark:bg-white/10"><div className="h-full rounded-full bg-gradient-to-r from-amber-400 to-amber-500" style={{ width: `${value?.skipped || !value?.max ? 0 : Math.min(100, (Number(value.achieved || 0) / Number(value.max || 1)) * 100)}%` }} /></div>\n                      </div>\n                    ))}\n                  </div>\n                </section>\n\n                <section className="mt-4 rounded-2xl border border-zinc-100 p-4 dark:border-white/10">\n                  <h3 className="mb-3 text-sm font-black text-zinc-950 dark:text-white">Performance History</h3>\n                  {drawerLoading && !drawerHistory.length ? <div className="h-36 animate-pulse rounded-xl bg-zinc-100 dark:bg-white/[0.05]" /> : <HistoryChart data={drawerHistory} />}\n                </section>\n\n                <section className="mt-4 rounded-2xl border border-zinc-100 p-4 dark:border-white/10">\n                  <div className="mb-3 flex items-center justify-between"><h3 className="text-sm font-black text-zinc-950 dark:text-white">Task Details</h3><Badge>{drawerTasks.length}</Badge></div>\n                  {!drawerTasks.length ? <p className="py-4 text-center text-xs font-bold text-zinc-400">No tasks in this period.</p> : (\n                    <div className="overflow-x-auto">\n                      <table className="w-full min-w-[620px] text-[11px]">\n                        <thead className="text-zinc-400"><tr><th className="py-2 text-left">Task</th><th className="py-2 text-left">Project</th><th className="py-2 text-left">Status</th><th className="py-2 text-left">Priority</th><th className="py-2 text-right">Hours</th><th className="py-2 text-right">Due</th><th /></tr></thead>\n                        <tbody className="divide-y divide-zinc-100 dark:divide-white/10">\n                          {drawerTasks.map((task) => (\n                            <tr key={task.id}>\n                              <td className="max-w-[220px] truncate py-2.5 pr-2 font-black text-zinc-900 dark:text-white">{task.title}</td>\n                              <td className="py-2.5 pr-2 text-zinc-500">{task.project?.name || task.projectName || "—"}</td>\n                              <td className="py-2.5 pr-2 text-zinc-500">{task.status || "—"}</td>\n                              <td className="py-2.5 pr-2 text-zinc-500">{task.priority || "—"}</td>\n                              <td className="py-2.5 text-right font-black">{formatHours(task.actualHours)}</td>\n                              <td className="py-2.5 text-right text-zinc-500">{formatDate(task.dueDate)}</td>\n                              <td className="py-2.5 pl-2 text-right">{onOpenTask ? <button type="button" onClick={() => onOpenTask(task)} className="rounded-lg border border-amber-200 px-2 py-1 font-black text-amber-700 hover:bg-amber-50 dark:border-amber-400/20 dark:text-amber-300 dark:hover:bg-amber-400/10">Open</button> : null}</td>\n                            </tr>\n                          ))}\n                        </tbody>\n                      </table>\n                    </div>\n                  )}\n                </section>\n\n                <section className="mt-4 rounded-2xl border border-zinc-100 p-4 dark:border-white/10">\n                  <div className="mb-3 flex items-center justify-between"><h3 className="text-sm font-black text-zinc-950 dark:text-white">Activity Timeline</h3><span className="text-[11px] font-bold text-zinc-400">{activityTotal} events</span></div>\n                  {!drawerActivities.length ? <p className="py-4 text-center text-xs font-bold text-zinc-400">No activity in this period.</p> : (\n                    <div className="space-y-3">\n                      {drawerActivities.map((activity) => (\n                        <div key={activity.id} className="flex gap-3">\n                          <div className="mt-1 h-2.5 w-2.5 shrink-0 rounded-full bg-amber-400" />\n                          <div className="min-w-0">\n                            <p className="text-xs font-black text-zinc-900 dark:text-white">{activityLabel(activity)}</p>\n                            <p className="mt-0.5 text-[11px] text-zinc-500">{activity.message || activity.task?.title || ""}</p>\n                            <p className="mt-0.5 text-[10px] font-bold text-zinc-400">{new Date(activity.createdAt).toLocaleString()}</p>\n                          </div>\n                        </div>\n                      ))}\n                      {drawerActivities.length < activityTotal ? <button type="button" disabled={drawerLoading} onClick={() => loadDrawer(selectedEmployee, activityPage + 1, true)} className="w-full rounded-xl border border-zinc-200 py-2 text-xs font-black text-zinc-600 hover:border-amber-300 disabled:opacity-50 dark:border-white/10 dark:text-zinc-300">Load more activity</button> : null}\n                    </div>\n                  )}\n                </section>\n              </div>\n            </div>\n          </aside>\n        </div>\n      ) : null}\n    </div>\n  );\n}\n\nexport default TeamPerformanceDashboard;\n'
API_INSERT = '    teamPerformance: (params = {}) => request(`/api/tasks/reports/team-performance${queryString(params)}`),\n    activities: (params = {}) => request(`/api/tasks/activities${queryString(params)}`),\n    teamPerformanceHistory: (params = {}) => request(`/api/tasks/reports/team-performance/history${queryString(params)}`),\n    exportTeamPerformance: (format, payload = {}) => downloadRequest(`/api/tasks/reports/team-performance/export/${encodeURIComponent(format)}`, {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify(payload || {}),\n    }),\n'

def run(repo, *args, check=True):
    result = subprocess.run(args, cwd=repo, text=True, capture_output=True)
    if check and result.returncode != 0:
        raise RuntimeError((result.stderr or result.stdout or "command failed").strip())
    return result

def ensure_clean_target(repo, rel):
    unstaged = run(repo, "git", "diff", "--quiet", "--", rel, check=False).returncode
    staged = run(repo, "git", "diff", "--cached", "--quiet", "--", rel, check=False).returncode
    if unstaged or staged:
        raise RuntimeError(f"Refusing to overwrite locally modified target: {rel}")

def main():
    if len(sys.argv) != 2:
        raise SystemExit("Usage: generate_phase4_true_final_management_dashboard_v1.py /var/www/TOS")
    repo = Path(sys.argv[1]).resolve()
    if not (repo / ".git").exists():
        raise RuntimeError(f"Not a git repository: {repo}")

    head = run(repo, "git", "rev-parse", "HEAD").stdout.strip()
    if head != BASELINE_HEAD:
        raise RuntimeError(f"Baseline mismatch: expected {BASELINE_HEAD}, got {head}")

    for rel in (BACKEND_REL, FRONTEND_REL, API_REL):
        ensure_clean_target(repo, rel)

    backend_path = repo / BACKEND_REL
    backend = backend_path.read_text(encoding="utf-8")
    start_marker = "// Team Performance Export Routes\n"
    end_marker = 'router.get("/reports/team-performance/history"'
    start = backend.find(start_marker)
    end = backend.find(end_marker, start + len(start_marker))
    if start < 0 or end < 0:
        raise RuntimeError("Could not locate the current Phase 4 export block")
    backend = backend[:start] + BACKEND_EXPORT_BLOCK.rstrip() + "\n" + backend[end:]
    backend_path.write_text(backend, encoding="utf-8")

    api_path = repo / API_REL
    api_source = api_path.read_text(encoding="utf-8")
    if "exportTeamPerformance:" in api_source:
        raise RuntimeError("Team Performance API wrappers already exist; refusing duplicate patch")
    needle = '    userDashboard: (params = {}) => request(`/api/tasks/reports/user-dashboard${queryString(params)}`),\n'
    if needle not in api_source:
        raise RuntimeError("Could not locate tasks.userDashboard API insertion point")
    api_source = api_source.replace(needle, needle + API_INSERT, 1)
    api_path.write_text(api_source, encoding="utf-8")

    frontend_path = repo / FRONTEND_REL
    frontend_path.write_text(FRONTEND_SOURCE.rstrip() + "\n", encoding="utf-8")

    print("PHASE4_TRUE_FINAL_MANAGEMENT_DASHBOARD_V1_APPLIED=YES")
    print("BACKEND_EXPORT_USES_PHASE3_CALCULATOR=YES")
    print("FRONTEND_OLD_EMPLOYEE_DASHBOARD_REMOVED=YES")
    print("FRONTEND_SINGLE_MANAGEMENT_VIEW=YES")
